def main():
    spec = {"wave": "mori-r51-w1", "reportDir": ".ufo/waves/round-51/w1", "context": context, "items": items}
    with open(os.path.join(W, "w1-spec.json"), "w") as f:
        json.dump(spec, f, indent=1)
    roles = {}
    for it in items:
        roles[it["role"]] = roles.get(it["role"], 0) + 1
    flash = sum(v for k, v in roles.items() if k in ("executor", "scribe", "sentinel", "simplifier", "revenger"))
    attack = sum(v for k, v in roles.items() if k in ("reviewer", "critic", "mutation-tester"))
    print(len(items), roles, "flash=%d attack=%d" % (flash, attack))

